/**
 * build-binary.ts — build dist-bin/babelgate, the single-executable
 * binary (v1.6 spec §3.2, D1). Node 24 LTS only: SEA assets and
 * node:sqlite are more mature there than on 22 (spec §3.2), and the
 * blob must be generated by the same Node version it is injected into.
 *
 *   ts-node scripts/build-binary.ts [--out dist-bin/] [--node <path>]
 *
 * Pipeline: `npm run build` → esbuild bundles dist/cli.js into one
 * CommonJS file (platform node, target node24, no externals beyond
 * node:* builtins) → a sea-config.json-derived config with every
 * dist/ui file as a `ui/…` asset → `node --experimental-sea-config`
 * makes the blob → the running Node binary is copied → postject
 * injects the blob (Node 24 has no built-in builder — the SEA docs
 * still prescribe postject) → on darwin the signature is removed
 * first and ad-hoc re-signed after (D2, no Apple identity).
 */
import { execFileSync } from "node:child_process";
import {
  chmodSync,
  copyFileSync,
  mkdirSync,
  mkdtempSync,
  readdirSync,
  readFileSync,
  statSync,
  writeFileSync,
} from "node:fs";
import { isAbsolute, join, relative, resolve, sep } from "node:path";
import { parseArgs } from "node:util";
import { buildSync } from "esbuild";

const REPO = resolve(__dirname, "..");

/** postject ships no type declarations — only the used surface. */
const { inject } = require("postject") as {
  inject: (
    filename: string,
    resourceName: string,
    resourceData: Buffer,
    options?: { sentinelFuse?: string; machoSegmentName?: string },
  ) => Promise<void>;
};

const SENTINEL_FUSE = "NODE_SEA_FUSE_fce680ab2cc467b6e072b8b5df1996b2";

function parseCli(argv: string[]): { out: string; node: string } {
  const { values } = parseArgs({
    args: argv,
    strict: true,
    options: {
      out: { type: "string" },
      node: { type: "string" },
    },
  });
  return {
    out:
      values.out !== undefined
        ? resolve(process.cwd(), values.out)
        : join(REPO, "dist-bin"),
    node: values.node ?? process.execPath,
  };
}

function nodeMajor(nodePath: string): number {
  const version =
    nodePath === process.execPath
      ? process.versions.node
      : execFileSync(nodePath, ["--version"], { encoding: "utf8" })
          .trim()
          .replace(/^v/, "");
  return parseInt(version.split(".")[0], 10);
}

/** Every file under dist/ui as a `ui/<relative path>` SEA asset. */
function uiAssets(uiDir: string): Record<string, string> {
  const assets: Record<string, string> = {};
  const walk = (dir: string): void => {
    for (const entry of readdirSync(dir, { withFileTypes: true })) {
      const path = join(dir, entry.name);
      if (entry.isDirectory()) {
        walk(path);
      } else {
        assets[`ui/${relative(uiDir, path).split(sep).join("/")}`] = path;
      }
    }
  };
  walk(uiDir);
  return assets;
}

async function main(): Promise<void> {
  const { out, node } = parseCli(process.argv.slice(2));
  if (nodeMajor(process.execPath) !== 24 || nodeMajor(node) !== 24) {
    throw new Error(
      `build-binary must run on Node 24.x (got ${process.versions.node}` +
        `${node === process.execPath ? "" : `, --node ${node}`})`,
    );
  }

  mkdirSync(out, { recursive: true });
  mkdirSync(join(REPO, "tmp"), { recursive: true });
  const tmp = mkdtempSync(join(REPO, "tmp", "sea-"));

  console.log("[build-binary] npm run build");
  execFileSync("npm", ["run", "build"], { cwd: REPO, stdio: "inherit" });

  const bundle = join(out, "babelgate.cjs");
  console.log(`[build-binary] esbuild → ${bundle}`);
  buildSync({
    entryPoints: [join(REPO, "dist", "cli.js")],
    bundle: true,
    platform: "node",
    format: "cjs",
    target: "node24",
    outfile: bundle,
    logLevel: "warning",
  });

  // The committed sea-config.json carries the flags; main/output and
  // the generated asset map are resolved here so the file stays a
  // stable description rather than a build artifact.
  const baseConfig = JSON.parse(
    readFileSync(join(REPO, "sea-config.json"), "utf8"),
  ) as Record<string, unknown>;
  const blob = join(tmp, "sea-prep.blob");
  const mergedConfig = {
    ...baseConfig,
    main: bundle,
    output: blob,
    assets: uiAssets(join(REPO, "dist", "ui")),
  };
  const configPath = join(tmp, "sea-config.json");
  writeFileSync(configPath, JSON.stringify(mergedConfig));

  console.log("[build-binary] node --experimental-sea-config → blob");
  execFileSync(node, ["--experimental-sea-config", configPath], {
    stdio: "inherit",
  });

  const outName =
    process.platform === "win32" ? "babelgate.exe" : "babelgate";
  const outPath = join(out, outName);
  copyFileSync(node, outPath);

  if (process.platform === "darwin") {
    execFileSync("codesign", ["--remove-signature", outPath], {
      stdio: "inherit",
    });
  }
  console.log(`[build-binary] postject → ${outPath}`);
  await inject(outPath, "NODE_SEA_BLOB", readFileSync(blob), {
    sentinelFuse: SENTINEL_FUSE,
    ...(process.platform === "darwin"
      ? { machoSegmentName: "NODE_SEA" }
      : {}),
  });
  if (process.platform === "darwin") {
    // D2: ad-hoc re-sign only — no Apple identity in v1.6.
    execFileSync("codesign", ["--sign", "-", outPath], {
      stdio: "inherit",
    });
  }
  chmodSync(outPath, 0o755);

  const mib = statSync(outPath).size / (1024 * 1024);
  console.log(`[build-binary] ${outPath} (${mib.toFixed(1)} MiB)`);
}

main().catch((err) => {
  console.error(err instanceof Error ? err.message : String(err));
  process.exit(1);
});
